function truncate(input, maxLength, suffix = '…', options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;

  const budget = Math.max(0, maxLength - suffix.length);
  let head = s.slice(0, budget);

  if (options.wordBoundary) {
    // Only trim back when the cut actually landed inside a word — if the next character is
    // whitespace, the last word ended exactly on the budget and is kept whole.
    if (!/\s/.test(s.charAt(budget))) {
      const lastSpace = head.search(/\s+\S*$/);
      // No boundary at all (one long word): a hard cut is the only thing that fits.
      if (lastSpace > 0) head = head.slice(0, lastSpace);
    }
    head = head.replace(/\s+$/, '');
  }

  return head + suffix;
}

