  assert.strictEqual(wordCount('# Heading here'), 2);
  assert.strictEqual(wordCount('### Deep heading'), 2);
  assert.strictEqual(wordCount('- one\n- two'), 2);
  assert.strictEqual(wordCount('* one\n+ two\n1. three'), 3);
  assert.strictEqual(wordCount('> quoted line'), 2);
  assert.strictEqual(wordCount('---'), 0);

