'use strict';

// Text utilities. Small on purpose: the interesting part is the backlog, not the code.

const ACRONYMS = new Set(['API', 'HTTP', 'SQL', 'URL', 'CSS']);

// Lowercase Cyrillic -> Latin. Applied after toLowerCase(), so only lowercase keys are needed.
const CYRILLIC_TO_LATIN = {
  а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'e', ж: 'zh', з: 'z',
  и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r',
  с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh',
  щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya',
  // Ukrainian / Belarusian extras, so they transliterate rather than vanish.
  і: 'i', ї: 'yi', є: 'ye', ґ: 'g', ў: 'u',
};

function transliterate(s) {
  let out = '';
  for (const ch of s) {
    out += Object.prototype.hasOwnProperty.call(CYRILLIC_TO_LATIN, ch) ? CYRILLIC_TO_LATIN[ch] : ch;
  }
  return out;
}

function slugify(input) {
  return transliterate(String(input).trim().toLowerCase())
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function truncate(input, maxLength, suffix = '…', options = {}) {
  const s = String(input);
  if (s.length <= maxLength) return s;

  const budget = Math.max(0, maxLength - suffix.length);
  let head = s.slice(0, budget);

  if (options.wordBoundary) {
    // Only trim back when the cut actually landed inside a word — if the next character is
    // whitespace, the last word ended exactly on the budget and is kept whole.
    if (!/\s/.test(s.charAt(budget))) {
      const lastSpace = head.search(/\s+\S*$/);
      // No boundary at all (one long word): a hard cut is the only thing that fits.
      if (lastSpace > 0) head = head.slice(0, lastSpace);
    }
    head = head.replace(/\s+$/, '');
  }

  return head + suffix;
}

function capitalize(input) {
  const s = String(input);
  if (!s) return s;
  return s[0].toUpperCase() + s.slice(1);
}

// Reduce markdown to the words a reader actually sees. Order matters: images before links (an
// image is a link with a leading '!'), links before the emphasis-marker strip (which would eat the
// '*' and '_' inside a URL).
function stripMarkdown(input) {
  return String(input)
    // Images: the reader sees a picture, not the alt text.
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/!\[[^\]]*\]\[[^\]]*\]/g, ' ')
    // Links: keep the text, drop the target (and any link title).
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\[([^\]]*)\]\[[^\]]*\]/g, '$1')
    .replace(/\[([^\]]*)\]/g, '$1')
    // Autolinked / bare-angle URLs are chrome, not words.
    .replace(/<https?:\/\/[^>]*>/g, ' ')
    // Horizontal rules would otherwise survive as a stray token.
    .replace(/^[ \t]*([-*_])(?:[ \t]*\1){2,}[ \t]*$/gm, ' ')
    // Leading line syntax: heading hashes, blockquote markers, list bullets.
    .replace(/^[ \t]*#{1,6}[ \t]+/gm, '')
    .replace(/^[ \t]*>+[ \t]?/gm, '')
    .replace(/^[ \t]*(?:[-+*]|\d+[.)])[ \t]+/gm, '')
    // Code fences: the code itself is words, the fence is not.
    .replace(/^[ \t]*(?:```|~~~).*$/gm, ' ')
    // Emphasis / code markers. Dropping these characters can never split or merge words, so the
    // count is unaffected for things like snake_case.
    .replace(/[*_~`]/g, '');
}

function wordCount(input) {
  const s = stripMarkdown(input).trim();
  if (!s) return 0;
  return s.split(/\s+/).length;
}

const HTML_ENTITIES = {
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;',
};

// One pass over the source string, so the '&' rule comes first by construction: the '&' this
// function emits is never itself a candidate for escaping, and '&lt;' in the input becomes
// '&amp;lt;' exactly once.
function escapeHtml(input) {
  return String(input).replace(/[&<>"']/g, (ch) => HTML_ENTITIES[ch]);
}

const WORDS_PER_MINUTE = 200;

// Whole minutes, never zero for text that has words. Rounded rather than ceiled: "minimum 1" is
// what covers everything shorter than half a minute of reading.
function readingTime(input) {
  const words = wordCount(input);
  if (words === 0) return 0;
  return Math.max(1, Math.round(words / WORDS_PER_MINUTE));
}

// A caller's set replaces the built-in list rather than extending it — pass
// [...ACRONYMS, 'SDK'] to add to it. Any iterable of strings works; matching is case-insensitive.
function titleCase(input, acronyms = ACRONYMS) {
  const known = acronyms instanceof Set ? acronyms : new Set(acronyms);
  const upper = new Set();
  for (const a of known) upper.add(String(a).toUpperCase());

  return String(input)
    .split(/\s+/)
    .map((w) => (upper.has(w.toUpperCase()) ? w.toUpperCase() : capitalize(w.toLowerCase())))
    .join(' ');
}

module.exports = {
  slugify,
  truncate,
  capitalize,
  wordCount,
  readingTime,
  escapeHtml,
  titleCase,
  ACRONYMS,
};

