'use strict';
// Tests for the BACKLOG.md items. tests/text.test.js holds the pre-existing behaviour and is
// never edited; new behaviour is pinned here.
const test = require('node:test');
const assert = require('node:assert');
const {
  slugify,
  truncate,
  wordCount,
  readingTime,
  escapeHtml,
  titleCase,
  ACRONYMS,
} = require('../src/text');

const words = (n) => Array.from({ length: n }, (_, i) => `w${i}`).join(' ');

test('cyrillic-slug: slugify transliterates Cyrillic to Latin', () => {
  assert.strictEqual(slugify('Привет мир'), 'privet-mir');
  assert.strictEqual(slugify('Ёжик'), 'ezhik');
  assert.strictEqual(slugify('Щука'), 'shchuka');
  // Latin behaviour is unchanged.
  assert.strictEqual(slugify('Hello World'), 'hello-world');
  assert.strictEqual(slugify('  Spaces  everywhere  '), 'spaces-everywhere');
  // Mixed scripts still produce one clean slug.
  assert.strictEqual(slugify('Node.js и Привет'), 'node-js-i-privet');
});

test('truncate-word-boundary: wordBoundary never cuts mid-word', () => {
  // Default behaviour is untouched.
  assert.strictEqual(truncate('The quick brown fox', 12), 'The quick b…');
  assert.strictEqual(truncate('The quick brown fox', 12, '…', {}), 'The quick b…');

  assert.strictEqual(truncate('The quick brown fox', 12, '…', { wordBoundary: true }), 'The quick…');
  assert.strictEqual(truncate('The quick brown fox', 14, '...', { wordBoundary: true }), 'The quick...');
  // Short enough to keep whole: no suffix at all.
  assert.strictEqual(truncate('short', 20, '…', { wordBoundary: true }), 'short');
  // A word ending exactly on the budget is kept whole.
  assert.strictEqual(truncate('The quick brown fox', 10, '…', { wordBoundary: true }), 'The quick…');
  // One long word has no boundary to fall back to; a hard cut is all that fits.
  assert.strictEqual(truncate('supercalifragilistic', 8, '…', { wordBoundary: true }), 'superca…');
  // The result must always still fit the limit.
  for (const max of [4, 7, 9, 13, 18]) {
    const out = truncate('The quick brown fox', max, '…', { wordBoundary: true });
    assert.ok(out.length <= max, `max=${max} exceeded by ${JSON.stringify(out)}`);
  }
});

test('word-count-markdown: counts the words a reader sees', () => {
  // Plain text is unchanged.
  assert.strictEqual(wordCount('one two three'), 3);
  assert.strictEqual(wordCount('   '), 0);

  // Heading hashes, bullets and blockquote markers are not words.
  assert.strictEqual(wordCount('# Heading here'), 2);
  assert.strictEqual(wordCount('### Deep heading'), 2);
  assert.strictEqual(wordCount('- one\n- two'), 2);
  assert.strictEqual(wordCount('* one\n+ two\n1. three'), 3);
  assert.strictEqual(wordCount('> quoted line'), 2);
  assert.strictEqual(wordCount('---'), 0);

  // Emphasis markers are not words and do not split the word they wrap.
  assert.strictEqual(wordCount('**bold** text'), 2);
  assert.strictEqual(wordCount('*a* _b_ __c__ ~~d~~ `e`'), 5);
  assert.strictEqual(wordCount('snake_case_name'), 1);

  // Link text counts, the URL and the link title do not.
  assert.strictEqual(wordCount('see [the docs](https://example.com/a/b) now'), 4);
  assert.strictEqual(wordCount('[text](https://example.com "Some Title")'), 1);
  assert.strictEqual(wordCount('[the docs][ref]'), 2);
  // An image shows a picture, not words.
  assert.strictEqual(wordCount('![alt text](https://example.com/img.png)'), 0);

  const doc = '# Title\n\nSome **bold** words and [a link](https://example.com/x).\n\n- first item\n- second item\n';
  // Title | Some bold words and a link. | first item | second item
  assert.strictEqual(wordCount(doc), 11);
});

test('reading-time: whole minutes at 200 wpm, minimum 1 for non-empty', () => {
  assert.strictEqual(readingTime(''), 0);
  assert.strictEqual(readingTime('   '), 0);

  assert.strictEqual(readingTime('a single line'), 1);
  assert.strictEqual(readingTime(words(1)), 1);
  assert.strictEqual(readingTime(words(200)), 1);
  assert.strictEqual(readingTime(words(300)), 2);
  assert.strictEqual(readingTime(words(400)), 2);
  assert.strictEqual(readingTime(words(1000)), 5);
  // Rounded, not ceiled — "minimum 1" is what carries the short-text case.
  assert.strictEqual(readingTime(words(250)), 1);
  // Markdown syntax must not buy reading time.
  assert.strictEqual(readingTime('# ' + words(100)), readingTime(words(100)));
});

test('escape-html: escapes the five characters, ampersand first', () => {
  assert.strictEqual(escapeHtml(''), '');
  assert.strictEqual(escapeHtml('plain text'), 'plain text');
  assert.strictEqual(escapeHtml('&'), '&amp;');
  assert.strictEqual(escapeHtml('<'), '&lt;');
  assert.strictEqual(escapeHtml('>'), '&gt;');
  assert.strictEqual(escapeHtml('"'), '&quot;');
  assert.strictEqual(escapeHtml("'"), '&#39;');

  assert.strictEqual(
    escapeHtml('<a href="x">Tom & Jerry\'s</a>'),
    '&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&#39;s&lt;/a&gt;'
  );

  // The ampersand rule wins: an entity in the input is escaped once, not twice.
  assert.strictEqual(escapeHtml('&lt;'), '&amp;lt;');
  assert.strictEqual(escapeHtml('&amp;'), '&amp;amp;');
  // And escaping is idempotent-safe in the sense that a second pass keeps growing predictably,
  // never producing '&amp;amp;lt;' from a single pass over '&lt;'.
  assert.strictEqual(escapeHtml(escapeHtml('<')), '&amp;lt;');

  // A script payload comes out inert.
  assert.strictEqual(
    escapeHtml('<script>alert("xss")</script>'),
    '&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;'
  );
});

test('acronyms-configurable: titleCase takes a caller-supplied acronym set', () => {
  // Built-in list is still the default.
  assert.strictEqual(titleCase('the http api'), 'The HTTP API');

  // A caller's set replaces the default.
  assert.strictEqual(titleCase('the acme sdk', ['SDK']), 'The Acme SDK');
  assert.strictEqual(titleCase('the http api', ['SDK']), 'The Http Api');

  // Set, array and lowercase entries all work.
  assert.strictEqual(titleCase('the acme sdk', new Set(['SDK'])), 'The Acme SDK');
  assert.strictEqual(titleCase('the acme sdk', ['sdk']), 'The Acme SDK');

  // Extending the built-ins is spelled out explicitly by the caller.
  assert.strictEqual(titleCase('the http sdk', [...ACRONYMS, 'SDK']), 'The HTTP SDK');

  // Passing an empty set means no acronyms at all.
  assert.strictEqual(titleCase('the http api', []), 'The Http Api');

  // The default set is not mutated by any of this.
  assert.ok(!ACRONYMS.has('SDK'));
});

